public int countNumbersWithUniqueDigits(int n) {
    if (n == 0) return 1;
    int count = 10;          // all single digits 0-9
    int unique = 9;          // running product for current length
    int available = 9;       // digits still free for next position
    for (int i = 2; i <= n; i++) {
        unique *= available; // extend from length i-1 to i
        count += unique;
        available--;
    }
    return count;
}

public int atMostNGivenDigitSet(String[] digits, int n) {
    String s = String.valueOf(n);
    int K = s.length();
    int D = digits.length;
    int[] pow = new int[K + 1];
    pow[0] = 1;
    for (int i = 1; i <= K; i++) pow[i] = pow[i - 1] * D;
    int ans = 0;
    // numbers with fewer digits than n
    for (int i = 1; i < K; i++) ans += pow[i];
    // numbers with exactly K digits, staying <= n
    for (int i = 0; i < K; i++) {
        char c = s.charAt(i);
        boolean matched = false;
        for (String d : digits) {
            char dc = d.charAt(0);
            if (dc < c) {
                ans += pow[K - i - 1];   // this position smaller -> rest free
            } else if (dc == c) {
                matched = true;          // can keep tight prefix
            }
        }
        if (!matched) return ans;        // cannot match n[i], no more equal prefixes
    }
    return ans + 1;                      // n itself is formable
}

class Solution {
    int MOD = 1_000_000_007;
    int minS, maxS;
    Integer[][] dp;

    public int count(String num1, String num2, int min_sum, int max_sum) {
        this.minS = min_sum;
        this.maxS = max_sum;
        int a = solve(num2);        // count in [0, num2]
        int b = solve(num1);        // count in [0, num1]
        int res = ((a - b) % MOD + MOD) % MOD;   // (num1, num2]
        int s = 0;
        for (int i = 0; i < num1.length(); i++) s += num1.charAt(i) - '0';
        if (s >= minS && s <= maxS) res = (res + 1) % MOD;   // add back num1
        return res;
    }

    int solve(String num) {
        dp = new Integer[num.length()][maxS + 1];
        return dfs(num, 0, 0, true);
    }

    int dfs(String num, int idx, int sum, boolean tight) {
        if (sum > maxS) return 0;
        if (idx == num.length()) return sum >= minS ? 1 : 0;
        if (!tight && dp[idx][sum] != null) return dp[idx][sum];
        int limit = tight ? num.charAt(idx) - '0' : 9;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            res += dfs(num, idx + 1, sum + d, tight && d == limit);
        }
        res %= MOD;
        if (!tight) dp[idx][sum] = (int) res;
        return (int) res;
    }
}

public int numDupDigitsAtMostN(int n) {
    return n - countUnique(n);
}

private int countUnique(int n) {
    String s = String.valueOf(n);
    int K = s.length();
    int res = 0;
    // numbers with fewer digits than n
    for (int i = 1; i < K; i++) res += 9 * perm(9, i - 1);
    // equal length, distinct, tight scan
    boolean[] used = new boolean[10];
    for (int i = 0; i < K; i++) {
        int cur = s.charAt(i) - '0';
        for (int d = (i == 0 ? 1 : 0); d < cur; d++) {
            if (!used[d]) res += perm(9 - i, K - i - 1);
        }
        if (used[cur]) return res;   // n has a repeat in its prefix, stop
        used[cur] = true;
        if (i == K - 1) res += 1;    // n itself is all-distinct
    }
    return res;
}

// permutations: m * (m-1) * ... * (m-k+1)
private int perm(int m, int k) {
    int r = 1;
    for (int i = 0; i < k; i++) r *= (m - i);
    return r;
}

public int countSpecialNumbers(int n) {
    String s = String.valueOf(n);
    int K = s.length();
    long res = 0;
    // fewer digits than n
    for (int i = 1; i < K; i++) res += 9L * perm(9, i - 1);
    // same length, tight
    boolean[] used = new boolean[10];
    for (int i = 0; i < K; i++) {
        int cur = s.charAt(i) - '0';
        for (int d = (i == 0 ? 1 : 0); d < cur; d++) {
            if (!used[d]) res += perm(9 - i, K - i - 1);
        }
        if (used[cur]) return (int) res;   // repeat in n's prefix
        used[cur] = true;
        if (i == K - 1) res += 1;          // n itself is special
    }
    return (int) res;
}

