}

public int findIntegers(int n) {
    int[] f = new int[32];
    f[0] = 1;
    f[1] = 2;
    for (int i = 2; i < 32; i++) f[i] = f[i - 1] + f[i - 2];
    int prevBit = 0, res = 0;
    for (int i = 30; i >= 0; i--) {
        if ((n & (1 << i)) != 0) {
            res += f[i];                 // put 0 here, rest of bits free & valid
            if (prevBit == 1) return res; // n has adjacent ones -> stop, n invalid
            prevBit = 1;
        } else {
            prevBit = 0;
        }
    }
    return res + 1;                       // include n itself
}

class Solution {
    public int rob(TreeNode root) {
        int[] r = dfs(root);
        return Math.max(r[0], r[1]);
    }

    // r[0] = best if this node NOT robbed, r[1] = best if robbed
    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};
        int[] l = dfs(node.left);
        int[] r = dfs(node.right);
        int skip = Math.max(l[0], l[1]) + Math.max(r[0], r[1]);
        int rob = node.val + l[0] + r[0];
        return new int[]{skip, rob};
    }
}

