class Solution {
    private int cameras = 0;

    public int minCameraCover(TreeNode root) {
        if (dfs(root) == 0) cameras++;   // root uncovered -> cover it
        return cameras;
    }

    // 0 = uncovered, 1 = covered (no camera), 2 = has camera
    private int dfs(TreeNode node) {
        if (node == null) return 1;      // null counts as covered
        int l = dfs(node.left);
        int r = dfs(node.right);
        if (l == 0 || r == 0) { cameras++; return 2; } // must cover a child
        if (l == 2 || r == 2) return 1;                // covered by a child's camera
        return 0;                                      // covered nowhere -> ask parent
    }
}

